// src/utils/reference.ts
function normalizeReferences(reference) {
  if (!reference) return void 0;
  return Array.isArray(reference) ? reference : [reference];
}

// src/encodeURL.ts
function encodeURL(fields) {
  return "link" in fields ? encodeTransactionRequestURL(fields) : encodeTransferRequestURL(fields);
}
function encodeTransactionRequestURL({ link, label, message }) {
  const pathname = link.search ? encodeURIComponent(String(link).replace(/\/\?/, "?")) : String(link).replace(/\/$/, "");
  const url = new URL(SOLANA_PROTOCOL + pathname);
  if (label) {
    url.searchParams.append("label", label);
  }
  if (message) {
    url.searchParams.append("message", message);
  }
  return url;
}
function encodeTransferRequestURL({
  recipient,
  amount,
  splToken,
  reference,
  label,
  message,
  memo
}) {
  const pathname = recipient;
  const url = new URL(SOLANA_PROTOCOL + pathname);
  if (amount != null) {
    url.searchParams.append("amount", amount.toFixed(10).replace(/0+$/, "").replace(/\.$/, ""));
  }
  if (splToken) {
    url.searchParams.append("spl-token", splToken);
  }
  const refs = normalizeReferences(reference);
  if (refs) {
    for (const ref of refs) {
      url.searchParams.append("reference", ref);
    }
  }
  if (label) {
    url.searchParams.append("label", label);
  }
  if (message) {
    url.searchParams.append("message", message);
  }
  if (memo) {
    url.searchParams.append("memo", memo);
  }
  return url;
}

// src/findReference.ts
var FindReferenceError = class extends Error {
  name = "FindReferenceError";
};
async function findReference(rpc, reference, { commitment, ...options } = {}) {
  const signatures = await rpc.getSignaturesForAddress(reference, { ...options, ...commitment ? { commitment } : {} }).send();
  const length = signatures.length;
  if (!length) throw new FindReferenceError("not found");
  const oldest = signatures[length - 1];
  if (length < (options?.limit || 1e3)) return oldest;
  try {
    return await findReference(rpc, reference, {
      commitment,
      ...options,
      before: oldest.signature
    });
  } catch (error) {
    if (error instanceof FindReferenceError) return oldest;
    throw error;
  }
}

